// Package catalog holds the pre-parsed operation index that cchp ships inside
// the binary. It is generated by cmd/cchp-gen from the pinned upstream spec,
// spec/cli-overlay.yaml and spec/operation-policy.yaml, so discovery, help and
// policy checks work offline and start fast.
package catalog

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"io"
	"sort"
	"strings"
	"unicode"
)

// Coverage outcomes for an upstream operation.
const (
	StatusAvailable   = "available"
	StatusExcluded    = "excluded"
	StatusUnsupported = "unsupported"
)

// Risk classes from spec/operation-policy.yaml.
const (
	RiskRead        = "read"
	RiskWrite       = "write"
	RiskDestructive = "destructive"
)

// Response kinds decide how cchp renders a successful response.
const (
	ResponseJSON   = "json"
	ResponseStream = "stream"
	ResponseBinary = "binary"
	ResponseEmpty  = "empty"
)

// Catalog is the whole generated index.
type Catalog struct {
	Source     Source       `json:"source"`
	Groups     []Group      `json:"groups"`
	Operations []*Operation `json:"operations"`

	byID map[string]*Operation
}

// Source records where the pinned spec came from (spec/source.lock.json).
type Source struct {
	Repository     string `json:"repository"`
	Tag            string `json:"tag"`
	Commit         string `json:"commit"`
	SpecPath       string `json:"spec_path"`
	SpecSHA256     string `json:"spec_sha256"`
	Exporter       string `json:"exporter"`
	RestishModule  string `json:"restish_module"`
	RestishVersion string `json:"restish_version"`
}

// Group is a human command group such as "providers".
type Group struct {
	Name    string `json:"name"`
	Title   string `json:"title"`
	Summary string `json:"summary"`
}

// Operation is one upstream OpenAPI operation as cchp sees it.
type Operation struct {
	ID          string   `json:"id"`
	Method      string   `json:"method"`
	Path        string   `json:"path"`
	Group       string   `json:"group"`
	Name        string   `json:"name"`
	Aliases     []string `json:"aliases,omitempty"`
	Summary     string   `json:"summary"`
	Status      string   `json:"status"`
	Reason      string   `json:"reason,omitempty"`
	Public      bool     `json:"public,omitempty"`
	Params      []Param  `json:"params,omitempty"`
	Body        *Body    `json:"body,omitempty"`
	Response    Response `json:"response"`
	OrgHeader   bool     `json:"org_header,omitempty"`
	Idempotency bool     `json:"idempotency,omitempty"`
	Policy      Policy   `json:"policy"`
}

// Param is one path, query or header parameter the CLI exposes.
type Param struct {
	Name        string   `json:"name"`
	In          string   `json:"in"`
	Flag        string   `json:"flag"`
	Type        string   `json:"type"`
	ItemType    string   `json:"item_type,omitempty"`
	Required    bool     `json:"required,omitempty"`
	Enum        []string `json:"enum,omitempty"`
	Default     any      `json:"default,omitempty"`
	Description string   `json:"description,omitempty"`
}

// Body describes the request body.
type Body struct {
	ContentType string   `json:"content_type"`
	Required    bool     `json:"required"`
	Kind        string   `json:"kind"` // json, multipart, binary
	FileFields  []string `json:"file_fields,omitempty"`
}

// Response describes the success response.
type Response struct {
	Kind         string   `json:"kind"`
	ContentTypes []string `json:"content_types,omitempty"`
}

// Policy is the merged entry from spec/operation-policy.yaml.
type Policy struct {
	Risk         string      `json:"risk"`
	Classified   bool        `json:"classified"`
	Retry        bool        `json:"retry"`
	Permission   string      `json:"permission,omitempty"`
	SecretFields []string    `json:"secret_fields,omitempty"`
	Pagination   *Pagination `json:"pagination,omitempty"`
	Note         string      `json:"note,omitempty"`
	// Listing names the operation that lists a download's parts with their sizes
	// (same path parameters except the last, which names the part). An empty
	// download of a part it lists as not empty is a failure.
	Listing string `json:"listing,omitempty"`
}

// SecretOutput reports whether the operation returns a one-time secret that
// needs an explicit destination.
func (p Policy) SecretOutput() bool { return len(p.SecretFields) > 0 }

// Pagination tells cchp how to walk an operation's pages.
type Pagination struct {
	Style      string `json:"style" yaml:"style"` // cursor or page
	Param      string `json:"param" yaml:"param"`
	LimitParam string `json:"limit_param,omitempty" yaml:"limit_param"`
	Next       string `json:"next,omitempty" yaml:"next"`
	HasMore    string `json:"has_more,omitempty" yaml:"has_more"`
	Items      string `json:"items" yaml:"items"`
	Total      string `json:"total,omitempty" yaml:"total"`
}

// OperationSchemas holds the bundled JSON Schemas of one operation.
type OperationSchemas struct {
	Body     json.RawMessage `json:"body,omitempty"`
	Response json.RawMessage `json:"response,omitempty"`
}

// DecodeGzip parses the gzip-compressed catalog JSON produced by the generator.
func DecodeGzip(data []byte) (*Catalog, error) {
	var c Catalog
	if err := DecodeGzipJSON(data, &c); err != nil {
		return nil, err
	}
	c.byID = make(map[string]*Operation, len(c.Operations))
	for _, op := range c.Operations {
		c.byID[op.ID] = op
	}
	return &c, nil
}

// DecodeGzipJSON decompresses data and decodes the JSON inside into v.
func DecodeGzipJSON(data []byte, v any) error {
	zr, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return err
	}
	raw, err := io.ReadAll(zr)
	if err != nil {
		return err
	}
	return json.Unmarshal(raw, v)
}

// Get returns an operation by operationId.
func (c *Catalog) Get(id string) (*Operation, bool) {
	op, ok := c.byID[id]
	return op, ok
}

// Group returns a group by name.
func (c *Catalog) Group(name string) (Group, bool) {
	for _, g := range c.Groups {
		if g.Name == name {
			return g, true
		}
	}
	return Group{}, false
}

// Available returns the operations the CLI can call, in catalog order.
func (c *Catalog) Available() []*Operation {
	var out []*Operation
	for _, op := range c.Operations {
		if op.Status == StatusAvailable {
			out = append(out, op)
		}
	}
	return out
}

// InGroup returns the available operations of one group, sorted by name.
func (c *Catalog) InGroup(group string) []*Operation {
	var out []*Operation
	for _, op := range c.Operations {
		if op.Group == group && op.Status == StatusAvailable {
			out = append(out, op)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// Param returns the parameter with the given flag name.
func (op *Operation) Param(flag string) (Param, bool) {
	for _, p := range op.Params {
		if p.Flag == flag {
			return p, true
		}
	}
	return Param{}, false
}

// Command is the human command path, for example "providers list".
func (op *Operation) Command() string { return op.Group + " " + op.Name }

// Kebab turns an operationId such as listOrgProviders into list-org-providers.
func Kebab(s string) string {
	var b strings.Builder
	runes := []rune(s)
	for i, r := range runes {
		if unicode.IsUpper(r) {
			prevLower := i > 0 && (unicode.IsLower(runes[i-1]) || unicode.IsDigit(runes[i-1]))
			nextLower := i+1 < len(runes) && unicode.IsLower(runes[i+1])
			prevUpper := i > 0 && unicode.IsUpper(runes[i-1])
			if i > 0 && (prevLower || (prevUpper && nextLower)) {
				b.WriteByte('-')
			}
			b.WriteRune(unicode.ToLower(r))
			continue
		}
		if r == '_' || r == ' ' || r == '.' {
			b.WriteByte('-')
			continue
		}
		b.WriteRune(r)
	}
	return b.String()
}
